138	function compare(a, b) {
139	  if (a < b) return -1
140	  if (a > b) return +1
141	  return 0
142	}
143	
144	function compareSemver(a, b) {
145	  return (
146	    compare(parseInt(a[0]), parseInt(b[0])) ||
147	    compare(parseInt(a[1] || '0'), parseInt(b[1] || '0')) ||
148	    compare(parseInt(a[2] || '0'), parseInt(b[2] || '0'))
