152	// this follows the npm-like semver behavior
153	function semverFilterLoose(operator, range) {
154	  range = range.split('.').map(parseSimpleInt)
155	  if (typeof range[1] === 'undefined') {
156	    range[1] = 'x'
157	  }
158	  // ignore any patch version because we only return minor versions
159	  // range[2] = 'x'
