175	// this follows the npm-like semver behavior
176	function compareSemverLoose(version, range) {
177	  if (version[0] !== range[0]) {
178	    return version[0] < range[0] ? -1 : +1
179	  }
180	  if (range[1] === 'x') {
181	    return 0
182	  }
183	  if (version[1] !== range[1]) {
