416	  queries = prepareQueries(queries, opts)
417	  checkQueries(queries)
418	
419	  var needsPath = parseQueries(queries).some(function (node) {
420	    return QUERIES[node.type].needsPath
421	  })
422	  var context = {
423	    ignoreUnknownVersions: opts.ignoreUnknownVersions,
424	    dangerousExtend: opts.dangerousExtend,
425	    throwOnMissing: opts.throwOnMissing,
426	    mobileToDesktop: opts.mobileToDesktop,
427	    env: opts.env
428	  }
429	  // Removing to avoid using context.path without marking query as needsPath
430	  if (needsPath) {
