526	// Note op_mob is not included as its chromium versions are not in sync with Opera desktop
527	browserslist.desktopNames = {
528	  and_chr: 'chrome',
529	  and_ff: 'firefox',
530	  ie_mob: 'ie',
531	  android: 'chrome' // has extra processing logic
532	}
533	
534	// Aliases to work with joined versions like `ios_saf 7.0-7.1`
535	browserslist.versionAliases = {}
536	
537	browserslist.clearCaches = env.clearCaches
538	browserslist.parseConfig = env.parseConfig
539	browserslist.readConfig = env.readConfig
